import{initSql}from"../../entity/index.js";import{createBaseUserData}from"../../service/user.js";import{init as initToken}from"../../service/token.js";import{vToken}from"../../action/api-middleware.js";import{PublicReturn}from"../../common/public-return.js";import{getReqLimiter}from"../../action/req-limiter.js";import{update as updateRss}from"../../service/rss.js";import{update as updateSitemap}from"../../service/sitemap.js";export async function createRouter(e){await e.post("/system/init-data",{preHandler:[vToken,getReqLimiter(1,1e4)]},async function(e,t){await initSql(),await createBaseUserData().catch(()=>{}),await initToken(),t.send(new PublicReturn(200,"更新成功"))}),await e.put("/system/rss/update",{preHandler:[vToken,getReqLimiter(1,3e3)]},async function(e,t){await updateRss(),t.send(new PublicReturn(200,"更新成功"))}),await e.put("/system/sitemap/update",{preHandler:[vToken,getReqLimiter(1,3e3)]},async function(e,t){await updateSitemap(),t.send(new PublicReturn(200,"更新成功"))})}